 static readonly BindingFlags Private=BindingFlags.Instance|BindingFlags.NonPublic;
 static T Field<T>(MainForm form,string name){return (T)typeof(MainForm).GetField(name,Private).GetValue(form);}static object Call(MainForm form,string name,params object[] args){return typeof(MainForm).GetMethod(name,Private).Invoke(form,args);}static void Check(bool ok,string message){if(!ok)throw new Exception(message);}static void Wait(Task task){var watch=Stopwatch.StartNew();while(!task.IsCompleted){Application.DoEvents();Thread.Sleep(10);if(watch.ElapsedMilliseconds>30000)throw new Exception("Language test timed out");}task.GetAwaiter().GetResult();}
