  var test=Path.Combine(stage,"mock-"+mode+".ps1");File.WriteAllText(test,prefix+helper.Substring(body),new UTF8Encoding(true));using(var process=Process.Start(new ProcessStartInfo(OcrLanguageService.PowerShell(),"-NoProfile -NonInteractive -ExecutionPolicy Bypass -File "+Backend.Quote(test)){UseShellExecute=false,CreateNoWindow=true})){Check(process.WaitForExit(10000),"Mock installer hung");int code=process.ExitCode;var calls=File.Exists(record)?File.ReadAllLines(record):new string[0];if(mode=="success"||mode=="restart")Check(calls.Length==2&&calls[0].StartsWith("Language.Basic~~~ja-JP~")&&calls[1].StartsWith("Language.OCR~~~ja-JP~"),"Install dependencies/order wrong");if(mode=="installed"||mode=="unsupported")Check(calls.Length==0,"Installer changed an installed or unavailable capability");return code;}
