   var preferences=Field<LanguagePreferences>(form,"languageSettings");string savedOcr=preferences.OcrTag;preferences.OcrTag=OcrLanguageService.CapabilityTag(installed.Result[0].Tag);Call(form,"PopulateOcrOptions");Check(!Field<ThemeCombo>(form,"windowsLanguageChoice").Text.Contains("not installed"),"Installed neutral/regional tag alias marked missing");preferences.OcrTag="zz-ZZ";Call(form,"PopulateOcrOptions");Field<ThemeCombo>(form,"extractMode").SelectedIndex=0;Field<TextBox>(form,"source").Text="Keep previous source";
   using(var dismiss=new System.Windows.Forms.Timer{Interval=70}){dismiss.Tick+=(s,e)=>{foreach(Form notice in Application.OpenForms)if(notice.Visible&&notice.Modal&&notice.Text=="Text extraction"){notice.Close();break;}};dismiss.Start();Wait((Task)Call(form,"ReadImage",Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"fixture.png"),false,true));dismiss.Stop();}Check(Field<byte[]>(form,"lastImage")!=null&&Field<TextBox>(form,"source").Text=="Keep previous source","Missing OCR pack discarded capture/source");preferences.OcrTag=savedOcr;Call(form,"PopulateOcrOptions");
   Call(form,"SelectSettingsCategory","Extraction & Translation");var settings=Field<Form>(form,"settingsWindow");settings.Show(form);Application.DoEvents();Field<TextBox>(form,"ocrSearch").Text="Greek";var ocr=Field<ListBox>(form,"ocrList");Check(ocr.Items.Count>=1,"OCR search failed");var row=ocr.Items.Cast<OcrPackRow>().FirstOrDefault(v=>v.Installed);if(row!=null){ocr.SelectedItem=row;Call(form,"UseSelectedOcr");Check(Field<LanguagePreferences>(form,"languageSettings").OcrTag==row.RecognizerTag,"Use OCR language failed");}
