   using(var frame=new Bitmap(settings.Width,settings.Height)){settings.DrawToBitmap(frame,new Rectangle(Point.Empty,settings.Size));frame.Save(Path.Combine(stage,"Languages-translation.png"));}settings.Hide();Field<TextBox>(form,"source").Text="Fixture source";Wait((Task)Call(form,"Translate","ja","Japanese"));Check(Field<TextBox>(form,"result").Text=="Fixture translation","New translation target rejected");Wait((Task)Call(form,"Translate","ar","Arabic"));Check(Field<TextBox>(form,"result").RightToLeft==RightToLeft.Yes,"RTL target not applied");
   var pickerDeadline=Stopwatch.StartNew();using(var choose=new System.Windows.Forms.Timer{Interval=80}){choose.Tick+=(s,e)=>{foreach(Form picker in Application.OpenForms)if(picker.Visible&&picker.Modal&&picker.Text=="Translate to"){var search=Descendants(picker).OfType<TextBox>().First(v=>v.AccessibleName=="Search translation language");search.Text="Japanese";var button=Descendants(picker).OfType<Button>().First(v=>v.Text=="Translate");if(button.Enabled&&button.CanSelect){typeof(Button).GetMethod("OnClick",Private).Invoke(button,new object[]{EventArgs.Empty});if(picker.DialogResult==DialogResult.OK){choose.Stop();return;}}if(pickerDeadline.ElapsedMilliseconds>10000){choose.Stop();picker.DialogResult=DialogResult.Cancel;}return;}};choose.Start();Wait((Task)Call(form,"ChooseTranslationLanguage"));}Check(Field<Label>(form,"resultTitle").Text.Contains("Japanese"),"More picker did not translate chosen target");form.Size=form.MinimumSize;Application.DoEvents();var quick=Field<Panel>(form,"translationLanguageRow");Check(quick.Controls.Cast<Control>().All(v=>v.Right<=quick.ClientSize.Width),"Quick languages/More clipped at minimum window size");Call(form,"ExitApplication");
  }

