  File.WriteAllText(args[0],"PASS: translation catalog/search incl. native names and Chinese/Portuguese variants; live installed OCR enumeration without elevation; explicit Windows default; installed tag alias mapping; missing pack retains image/source; OCR selection; More picker translation and minimum layout; independent target/default/favorites; max 3 quick languages; preference changes make no AI requests; Japanese/Arabic translation via isolated mock HTTP; RTL; persistence; restricted elevated install command; mocked Basic-before-OCR install, already-installed skip, unavailable/blocked/restart outcomes. No real packs were installed and no real AI requests were made.");return 0;
 }catch(Exception ex){File.WriteAllText(args[0],ex.ToString());return 1;}finally{if(prior==null){if(File.Exists(hint))File.Delete(hint);}else File.WriteAllText(hint,prior);}}
